<?php
/**
 * Compact CSS generated by Reflector.
 *
 * This minifier intentionally does not merge selectors or declarations: all
 * generated utility classes and their cascade/order are preserved.
 */
function minifyCSS(string $css): string
{
    $length = strlen($css);
    $out = '';
    $quote = null;
    $pendingSpace = false;
    $inComment = false;

    // Token-aware comment and whitespace pass. Quoted strings (including
    // content/url values) are copied byte-for-byte.
    for ($i = 0; $i < $length; $i++) {
        $ch = $css[$i];
        $next = $i + 1 < $length ? $css[$i + 1] : '';

        if ($inComment) {
            if ($ch === '*' && $next === '/') {
                $inComment = false;
                $i++;
            }
            continue;
        }

        if ($quote !== null) {
            if ($pendingSpace) {
                $out .= ' ';
                $pendingSpace = false;
            }
            $out .= $ch;
            if ($ch === '\\' && $i + 1 < $length) {
                $out .= $css[++$i];
            } elseif ($ch === $quote) {
                $quote = null;
            }
            continue;
        }

        if ($ch === '/' && $next === '*') {
            $inComment = true;
            $i++;
            continue;
        }

        if ($ch === '"' || $ch === "'") {
            if ($pendingSpace && needsCSSSpace($out, $ch)) {
                $out .= ' ';
            }
            $pendingSpace = false;
            $quote = $ch;
            $out .= $ch;
            continue;
        }

        if (ctype_space($ch)) {
            $pendingSpace = true;
            continue;
        }

        if ($pendingSpace) {
            if (needsCSSSpace($out, $ch)) {
                $out .= ' ';
            }
            $pendingSpace = false;
        }

        // Spaces around structural punctuation are unnecessary. Keep spaces
        // around + and - because they may be required by calc() expressions.
        if (str_contains('{:;}', $ch)) {
            $out = rtrim($out);
        }
        $out .= $ch;
    }

    $out = trim($out);

    // Remove optional final declaration semicolons. This does not change the
    // rule's declarations or selector set.
    $out = preg_replace('/;(?=})/', '', $out) ?? $out;

    // Minify decimal notation and zero length units only in declaration-value
    // segments, never in selectors, strings, comments, or custom properties.
    $out = minifyCSSDeclarationValues($out);

    return $out;
}

function needsCSSSpace(string $out, string $next): bool
{
    if ($out === '') {
        return false;
    }

    $prev = $out[strlen($out) - 1];

    // A space is unnecessary adjacent to these structural tokens.
    if (str_contains('{:;}', $prev) || str_contains('{:;}', $next)) {
        return false;
    }

    // Preserve descendant combinators, token separation, and calc operators.
    return true;
}

/** Apply value-only reductions while respecting strings and nested functions. */
function minifyCSSDeclarationValues(string $css): string
{
    $length = strlen($css);
    $out = '';
    $quote = null;
    $escaped = false;
    $depth = 0;
    $segmentStart = 0;
    $inDeclaration = false;
    $property = '';
    $value = '';

    // Deliberately conservative: declarations are transformed only when their
    // property/value boundary is unambiguous. Nested functions are preserved.
    for ($i = 0; $i < $length; $i++) {
        $ch = $css[$i];
        if ($quote !== null) {
            if ($escaped) { $escaped = false; continue; }
            if ($ch === '\\') { $escaped = true; continue; }
            if ($ch === $quote) { $quote = null; }
            continue;
        }
        if ($ch === '"' || $ch === "'") { $quote = $ch; continue; }
        if ($ch === '(' || $ch === '[') { $depth++; continue; }
        if ($ch === ')' || $ch === ']') { $depth = max(0, $depth - 1); continue; }

        if ($depth === 0 && ($ch === '{' || $ch === ';' || $ch === '}')) {
            $segment = substr($css, $segmentStart, $i - $segmentStart);
            if ($ch === '{') {
                $out .= $segment . $ch;
            } else {
                $out .= optimizeCSSDeclarationSegment($segment) . $ch;
            }
            $segmentStart = $i + 1;
        }
    }
    $out .= optimizeCSSDeclarationSegment(substr($css, $segmentStart));
    return $out;
}

function optimizeCSSDeclarationSegment(string $segment): string
{
    // Selector preludes and at-rule headers do not contain a declaration
    // property followed by a value in this segment; skip ambiguous segments.
    if (!preg_match('/^\s*(--[\w-]+|[a-zA-Z][\w-]*)\s*:(.*)$/s', $segment, $m)) {
        return $segment;
    }

    $property = strtolower($m[1]);
    if (str_starts_with($property, '--')) {
        return $segment;
    }

    $value = $m[2];
    // Do not rewrite quoted content or URLs. Split around strings and url(...)
    // so only plain value text is considered.
    $parts = preg_split('/("(?:\\\\.|[^"\\\\])*"|\'(?:\\\\.|[^\'\\\\])*\'|url\([^)]*\))/i', $value, -1, PREG_SPLIT_DELIM_CAPTURE);
    if ($parts === false) {
        return $segment;
    }

    foreach ($parts as $index => $part) {
        if ($index % 2 === 1) {
            continue;
        }
        // Unitless zero is valid for zero-valued CSS lengths.
        $part = preg_replace('/(?<![\w.-])0(?:px|rem|em|vh|vw|vmin|vmax|ch|ex|cm|mm|in|pt|pc)(?![\w-])/i', '0', $part) ?? $part;
        // Drop leading zero in decimal values (e.g. 0.5 -> .5).
        $part = preg_replace('/(?<![\w.#-])0\.(\d+)/', '.$1', $part) ?? $part;
        // Remove redundant trailing zeros in decimals (e.g. 1.500 -> 1.5).
        $part = preg_replace('/(?<![\w.#-])(\d+\.\d*?[1-9])0+(?=\D|$)/', '$1', $part) ?? $part;
        $parts[$index] = $part;
    }

    $optimized = implode('', $parts);
    $colon = strpos($segment, ':');
    if ($colon === false) {
        return $segment;
    }
    return substr($segment, 0, $colon + 1) . $optimized;
}
